    private FrameLayout viewport;private ScrollView railScroll,panelScroll;private LinearLayout rail,panel,panelBody;private TextView panelTitle,liveTrack,liveGps;private String panelType="",trackSignature="",poiSignature="";private final Map<Long,Button> downloadRows=new HashMap<>();private TextView areaStatus;private OfflineMaps.Area currentArea;private boolean panelCollapsed;private final Map<String,View> railButtons=new HashMap<>();
    private void buildRail(){rail.removeAllViews();railButtons.clear();railButton("map","Map view",()->showPanel("view"));railButton("layers","Layers",this::layers);railButton("gps","Center GPS",()->{centerPhone=true;host.gps();showPanel("gps");update();});railButton("fit","Fit nodes",this::fit);railButton("tracks","Tracks",()->showPanel("tracks"));railButton("download","Offline maps",this::offlineDialog);railButton("poi","Points of interest",this::pois);railButton("zoom+","Zoom in",()->{if(map!=null)map.animateCamera(CameraUpdateFactory.zoomIn());});railButton("zoom-","Zoom out",()->{if(map!=null)map.animateCamera(CameraUpdateFactory.zoomOut());});railButton("north","North up",()->{if(map!=null)map.resetNorth();});}
