    private void resizePanel(){if(viewport==null||viewport.getHeight()==0)return;int height=panel.getVisibility()==View.VISIBLE?(panelCollapsed?dp(48):Math.min(dp(360),(int)(viewport.getHeight()*.48))):0;FrameLayout.LayoutParams size=(FrameLayout.LayoutParams)panel.getLayoutParams();if(size.height!=height){size.height=height;panel.setLayoutParams(size);}FrameLayout.LayoutParams railSize=(FrameLayout.LayoutParams)railScroll.getLayoutParams();int space=Math.max(dp(46),viewport.getHeight()-height-dp(16));if(railSize.height!=space){railSize.height=space;railScroll.setLayoutParams(railSize);}if(map!=null)map.setPadding(0,0,dp(58),height);}
